pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // Penalize smaller residuals to favor tight packing.
    let mut score = post;

    // Penalty for creating "dead space" (small, unusable residuals).
    // If post_residual is in (0, 10), it's highly likely to be wasted.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to increase packing density.
    if next_item_size > 0 && (post_residual >= next_item_size) {
        score -= (next_item_size as f64) * 2.5;
    }

    // Dynamic thresholding: as we progress through the stream, 
    // become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin.
        // Penalty increases as we reach the end of the stream, 
        // forcing the use of existing open bins.
        score += 15.0 + (progress * 40.0);
    } else {
        // If this bin is the last one that can fit the item, 
        // give it a significant boost to prevent opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Coupling: If the mean residual of open bins is high, 
    // favor bins that are already "fuller" (lower residual).
    score += (mean_residual - post) * 0.5;

    score
}

