    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead zones": if the post_residual is too small to fit 
    // the next item (if it exists) or common item sizes, penalize it quadratically.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post).powf(1.5) * 2.0;
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower mean_residual).
    // If we are late in the stream, favor bins that maximize packing density (lower post_residual).
    let density_pressure = (mean_residual * progress).sqrt();
    score += density_pressure;

    // If this is the only bin that can fit the item, favor it heavily to avoid wasting 
    // a new bin unnecessarily, unless the post_residual is extremely poor (fragmentation).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // New Bin Logic: If bin_residual == bin_capacity, this is a fresh bin.
    // Only open a new bin if the current packing efficiency is already quite high
    // or if we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open
        } else {
            // Otherwise, heavily penalize opening a new bin to force packing into existing ones.
            score = 50.0 + (progress * 50.0);
        }
    }

    score
}

