pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic.
    // The objective is to minimize post_residual (Best-Fit) while penalizing "sliver" residuals
    // that are too small to fit common future items (Harmonic thresholds).

    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Residuals that cannot fit the mean item size (approx 40-50) 
    // are highly undesirable. We penalize small residues that aren't zero.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // 2. Lookahead Coupling: If the next item is large, favor bins that can accommodate it.
    // If post_residual cannot fit next_item_size, we increase the score (penalty).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. New Bin Thresholding: Prevent opening a new bin unless the current fits are terrible.
    // If this is a new bin (bin_residual == bin_capacity), only choose it if the
    // existing bins result in very poor packing density.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist.
            score += 60.0;
        } else {
            // If no bins fit, new bin is the only option.
            score -= 10.0;
        }
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly
    // from the average capacity usage to keep the distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Progression Scaling: As the stream nears completion, become more aggressive
    // about using existing open bins (Best-Fit behavior).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": gaps smaller than the smallest likely item (10) are extremely undesirable.
    // If post_residual is in [1, 9], it is likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: If this is an existing bin, penalize the score slightly to encourage
    // filling current bins rather than opening new ones, unless the fit is perfect.
    if bin_residual < bin_capacity {
        // Reward perfect fits (Best Fit)
        if post_residual == 0 {
            score -= 30.0;
        }
        // Penalize increasing the count of bins if we have many already open
        score += (open_bins_count as f64) * 0.5;
    } else {
        // This is the "New Bin" candidate path. 
        // Penalize opening a new bin heavily unless there are no good fits.
        score += 40.0 + (fitting_bins_count as f64 * 5.0);
    }

    // 4. Global balance: If we are near the end of the stream, prioritize space density.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit Decreasing logic (minimize post_residual).
    // Penalize small slivers (e.g., 1-5) that are too small for almost any item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: 
    // Favor residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This creates "bins" that are hospitable to future items.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 3. Lookahead Integration:
    // If next_item_size fits in the current post_residual, reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Scarcity/Density Balancing:
    // If we only have one bin that fits, we are forced to use it. 
    // Penalize opening a new bin if the current bin is "good enough".
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin unnecessarily
            score += 60.0;
        } else {
            // New bin is necessary
            score -= 10.0;
        }
    }

    // 5. Progression scaling:
    // As the stream nears completion, become more aggressive about filling existing bins
    // to avoid leaving leftovers at the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Mean Residual Equilibrium:
    // Avoid bins that deviate significantly from the current average density.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. Lower score is better.
    // We prioritize bins that result in a "tight" fit (low post_residual),
    // but penalize creating "fragmented" space that cannot fit common future items.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: Only do it if we are desperate or the fit is exceptionally poor.
    if is_new_bin {
        // Only consider a new bin if we have few options or the current average residual is high.
        score += 45.0 + (mean_residual * 0.5);
    } else {
        // If we are in an existing bin, check if this fit creates an unusable gap (e.g., < 10).
        // Small gaps are usually bad unless they are zero.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Lookahead heuristic: If the next item won't fit in the remaining space, 
        // penalize the current placement if it makes the bin "useless" for the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }

        // Global state: If we have too many open bins, prioritize filling them tightly.
        score += (open_bins_count as f64) * 2.0;

        // Dynamic horizon: As we near the end of the stream, prioritize closing bins (tight fits).
        score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;
    }

    // If this is the only bin that can fit the item, reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    score
}
